function head(title,subtitle='',actions=''){return `<div class="page-head"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><div class="flex wrap">${actions}</div></div>`;}
function stat(label,value,caption,icon){return `<div class="panel stat"><div class="flex between"><span class="label">${label}</span>${ico(icon)}</div><div class="value">${value}</div><div class="caption">${caption}</div></div>`;}
